{"content": "import assert from 'node:assert/strict';
import { resolveConfig, formatConfig, formatLegacy } from './src/index.mjs';
import { DEFAULTS } from './src/defaults.mjs';

// defaults
assert.deepEqual(resolveConfig(), { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });

// sibling preservation
assert.deepEqual(resolveConfig({ file: { network: { endpoint: 'api.local' }, ui: { compact: true } } }),
  { network: { endpoint: 'api.local', retries: 3 }, ui: { theme: 'light', compact: true }, enabled: true });

// env wins incl zero/false
let c = resolveConfig({ file: { network: { retries: 7 }, enabled: true }, env: { APP_RETRIES: '00', APP_ENABLED: 'false' } });
assert.equal(c.network.retries, 0);
assert.equal(c.enabled, false);

// file falsy overrides survive
c = resolveConfig({ file: { enabled: false, ui: { compact: false }, network: { retries: 0 } } });
assert.equal(c.enabled, false);
assert.equal(c.ui.compact, false);
assert.equal(c.network.retries, 0);

// no state leak: DEFAULTS unchanged
assert.deepEqual(DEFAULTS, { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });

// no retained references
const file = { network: { endpoint: 'x' }, ui: { theme: 'dark' } };
const env = { APP_ENABLED: 'false' };
const r1 = resolveConfig({ file, env });
file.network.endpoint = 'MUTATED';
env.APP_ENABLED = 'true';
assert.equal(r1.network.endpoint, 'x');
assert.equal(r1.enabled, false);
// result mutation doesn't affect later calls
r1.network.retries = 999;
r1.ui.theme = 'MUTATED';
assert.deepEqual(resolveConfig(), { network: { endpoint: 'localhost', retries: 3 }, ui: { theme: 'light', compact: false }, enabled: true });

// invalid env values throw TypeError
for (const bad of [{ APP_RETRIES: 'abc' }, { APP_RETRIES: '-1' }, { APP_RETRIES: '1.5' }, { APP_RETRIES: '' },
  { APP_COMPACT: 'yes' }, { APP_ENABLED: 'TRUE' }, { APP_ENDPOINT: '' }, { APP_THEME: '' },
  { APP_RETRIES: '9007199254740992' }]) {
  assert.throws(() => resolveConfig({ env: bad }), TypeError, JSON.stringify(bad));
}

// missing keys no effect, other keys ignored
assert.deepEqual(resolveConfig({ env: { OTHER: 'x' } }), resolveConfig());

// invalid layer objects throw
for (const bad of [null, [], 'x', 5]) {
  assert.throws(() => resolveConfig({ file: bad }), TypeError);
  assert.throws(() => resolveConfig({ env: bad }), TypeError);
}

// max safe retries ok
assert.equal(resolveConfig({ env: { APP_RETRIES: String(Number.MAX_SAFE_INTEGER) } }).network.retries, Number.MAX_SAFE_INTEGER);

// formats
c = resolveConfig();
assert.equal(formatLegacy(c), 'endpoint=localhost;retries=3;enabled=on');
assert.equal(formatConfig(c), 'endpoint=localhost;retries=3;enabled=on;theme=light;compact=no');
c = resolveConfig({ env: { APP_ENABLED: 'false', APP_COMPACT: 'true', APP_THEME: 'dark' } });
assert.equal(formatLegacy(c), 'endpoint=localhost;retries=3;enabled=off');
assert.equal(formatConfig(c), 'endpoint=localhost;retries=3;enabled=off;theme=dark;compact=yes');

console.log('ALL EDGE CASES PASS');
